<?php require __DIR__.'/app/bootstrap.php'; require __DIR__.'/includes/layout.php'; render_header('Новости'); ?><section class="section"><div class="container"><h1>Новости</h1><?php try{$rows=db()->query('SELECT * FROM csNews WHERE IsPublish=1 ORDER BY NewsDate DESC, ID DESC')->fetchAll();foreach($rows as $r):?><article class="content-card"><h2><?=htmlspecialchars(legacy($r['Title']??''))?></h2><p class="muted"><?=htmlspecialchars((string)($r['NewsDate']??''))?></p><?=legacy($r['ShortDescr']??'')?><?php if(!empty($r['FullDescr'])) echo legacy($r['FullDescr']);?></article><?php endforeach;}catch(Throwable $e){echo '<p>Новости временно недоступны.</p>';} ?></div></section><?php render_footer();
